<template>
 <view :class="['screen','page-'+page, { 'has-tabs': isTab, 'bottom-space': bottomSpace, mine: page==='mine', 'order-background': ['checkout','order-detail'].includes(page) }]">
  <view v-if="!isTab" class="nav" :style="nativeNavStyle"><text class="back" :style="nativeBackStyle" @click="back">‹</text><text>{{ title }}</text>
<!-- #ifdef H5 -->
<view class="capsule"><text>•••</text><text>━</text><text>⊙</text></view>
<!-- #endif -->
</view>
<view v-if="loading" class="loading">加载中…</view><view v-if="error" class="error-bar"><text>{{error}}</text><button class="error-retry" @click="refresh">重新加载</button></view>
  <template v-if="page==='home'">
   <view class="hero-wrap"><image :src="config.heroTop||'/static/brand/hero-top-jimeili-v2.jpg'" mode="widthFix" class="hero-top-art"/><view class="hero-middle-slot"><image :src="config.homeImage||'/static/brand/hero-middle.jpg'" mode="aspectFill" class="hero-middle-image"/></view><view class="hero-bottom-art"><image :src="config.heroBottom||'/static/brand/hero-bottom-v2.jpg'" mode="widthFix"/></view><view class="welcome-live"><view>美容 · 疗愈</view><view>静享肌肤时光</view><text>/ {{config.name||'暨美丽'}} 欢迎您的到来 /</text></view></view>
   <view class="shortcuts"><view v-for="s in shortcuts" :key="s.label" class="shortcut" @click="open(s.page,s.query)"><view class="shortcut-icon"><image :src="'/static/reference/shortcut-'+s.asset+'.png'" mode="aspectFit"/></view>{{ s.label }}</view></view>
   <view class="entry-grid"><view class="entry-left" @click="open('appointments')"><image src="/static/assets/booking.jpg" mode="widthFix"/></view><view class="entry-right"><image src="/static/assets/stores-entry.jpg" mode="widthFix" @click="open('stores')"/><image src="/static/assets/vip-entry.jpg" mode="widthFix" @click="open('activities')"/></view></view><image src="/static/assets/alliance-entry.jpg" class="alliance-entry" mode="widthFix" @click="open('alliances')"/><view v-for="module in homeModules" :key="module.id" class="home-module home-card" @click="homeModuleClick(module)"><image :src="module.image" mode="widthFix" class="wide-img"/><view class="card-copy"><view class="title">{{module.title}}</view><view v-if="module.subtitle" class="muted">{{module.subtitle}}</view><view v-if="module.description" class="description">{{module.description}}</view></view></view>
   <view v-for="s in stores" :key="s.id" class="home-card store-card" @click="open('stores')"><view class="store-visual"><image :src="s.image||config.storeDefaultImage||'/static/brand/store-cover-jimeili-v2.jpg'" class="wide-img" mode="widthFix"/></view><view class="card-copy"><view class="between"><text class="title">{{s.name}}</text><text class="pill">进入门店</text></view><view class="description">{{s.contact}}<view>门店地址：{{s.address}}</view></view></view></view>
<view class="home-section-heading home-category-heading"><image :src="config.serviceHeading||config.projectPromo||'/static/assets/service-heading.jpg'" mode="widthFix"/></view><view v-for="serviceProduct in featuredProducts" :key="serviceProduct.id" class="home-card home-product" :data-product-id="serviceProduct.id" @click="productPage(serviceProduct)"><image :src="serviceProduct.image||'/static/assets/product-placeholder.jpg'" mode="widthFix" class="wide-img" @error="imageError"/><view class="card-copy"><view class="title">{{serviceProduct.name}}</view><view class="price-lines"><text class="price">单次 ¥{{money(serviceProduct.price)}}</text><text v-if="serviceProduct.coursePrice!==undefined&&serviceProduct.coursePrice!==null" class="muted">疗程 ¥{{money(serviceProduct.coursePrice)}}</text></view><text class="pill product-buy">去抢购</text></view></view><view class="home-section-heading home-category-heading"><image :src="config.productHeading||'/static/assets/product-heading.jpg'" mode="widthFix"/></view><view v-for="goodsProduct in goodsProducts" :key="goodsProduct.id" class="home-card home-product" :data-product-id="goodsProduct.id" @click="productPage(goodsProduct)"><image :src="goodsProduct.image||'/static/assets/product-placeholder.jpg'" mode="widthFix" class="wide-img" @error="imageError"/><view class="card-copy"><view class="title">{{goodsProduct.name}}</view><view class="price-lines"><text class="price">单件 ¥{{money(goodsProduct.price)}}</text><text v-if="goodsProduct.coursePrice!==undefined&&goodsProduct.coursePrice!==null" class="muted">疗程 ¥{{money(goodsProduct.coursePrice)}}</text></view><text class="pill product-buy">去抢购</text></view></view><image :src="config.brand||'/static/brand/brand-jimeili.png'" class="brand-footer" mode="widthFix"/>
  </template>
  <template v-else-if="page==='mall'"><view class="nav mall-nav" :style="nativeNavStyle"><text class="mall-home" @click="switchTab('home')">⌂</text><text>商城</text><!-- #ifdef H5 --><view class="capsule"><text>•••</text><text>━</text><text>⊙</text></view><!-- #endif --></view><view class="mall-shell"><view class="mall-categories"><view v-for="c in mallCategories" :key="c.id" :class="['mall-category',{active:mallCategory===c.id}]" @click="mallCategory=c.id">{{c.name}}</view></view><view class="mall-content"><image class="mall-banner" :src="selectedMallCategoryName.includes('优选')?(config.productHeading||'/static/assets/product-heading.jpg'):(config.serviceHeading||config.projectPromo||config.welcome||'/static/assets/service-heading.jpg')" mode="aspectFill"/><view class="mall-heading">{{selectedMallCategoryName}}</view><view class="mall-product-list"><view v-for="p in mallProducts" :key="p.id" class="mall-product-row" @click="productPage(p)"><image class="mall-product-thumb" :src="p.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view class="mall-product-main"><view class="mall-product-name">{{p.name}}</view><view class="mall-store-tag">门店</view><view class="mall-price-row"><text class="mall-price">¥{{money(p.price)}}</text><text v-if="p.coursePrice!==undefined&&p.coursePrice!==null" class="mall-course-price">疗程 ¥{{money(p.coursePrice)}}</text></view></view><text class="pill mall-buy">去购买</text></view></view><view v-if="!mallProducts.length" class="mall-empty">暂无商品</view></view></view></template>
  <template v-else-if="page==='product' && product"><view class="product-cover-wrap"><image :src="product.image||product.detailImage||'/static/assets/product-placeholder.jpg'" class="product-cover" mode="widthFix" @error="imageError"/></view><view v-if="product.gallery&&product.gallery.length" class="product-gallery"><image v-for="url in product.gallery" :key="url" :src="url||product.detailImage||product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/></view><view class="product-info"><view class="title">{{product.name}}</view><view v-if="product.subtitle" class="muted product-subtitle">{{product.subtitle}}</view><view v-if="product.brand" class="muted">品牌：{{product.brand}}</view><text class="price-detail">会员价 {{money(unitPrice)}}元</text></view><view class="stock"><text>已售：{{product.sold}}件</text><text>库存：{{product.stock}}件</text></view><view class="section-title">商品详情</view><view class="detail-art-wrap"><image :src="product.detailImage||product.image||'/static/assets/product-placeholder.jpg'" class="detail-art" mode="widthFix" @error="imageError"/></view><view v-if="product.description" class="card rules">{{product.description}}</view><view class="bottom-actions"><view class="mini-action" @click="switchTab('home')"><image src="/static/reference/tab-home.png" mode="aspectFit"/>首页</view>
<!-- #ifdef MP-WEIXIN -->
<button class="mini-action" open-type="contact" session-from="product" show-message-card><image src="/static/reference/customer-service.png" mode="aspectFit"/>客服</button>
<!-- #endif -->
<!-- #ifdef H5 -->
<button class="mini-action" @click="contact"><image src="/static/reference/customer-service.png" mode="aspectFit"/>客服</button>
<!-- #endif --><button class="primary" @click="sheet=true">立即购买</button></view></template>
  <template v-else-if="page==='stores'"><view v-for="s in stores" :key="s.id" class="home-card store-page-card"><view class="store-visual"><image :src="s.image||config.storeDefaultImage||'/static/brand/store-cover-jimeili-v2.jpg'" class="wide-img" mode="widthFix"/></view><view class="store-page-copy"><view class="title">{{s.name}}</view><view class="description">{{s.contact}}<view>门店地址：{{s.address}}</view><view v-if="s.hours">营业时间：{{s.hours}}</view></view></view></view><view v-if="!stores.length" class="empty">暂无门店</view><view v-else class="empty">已经到底了～</view></template>
  <template v-else-if="page==='gifts'"><view class="gift-page-intro"><view class="gift-page-title">~可免费领取任意{{config.maxGifts}}件~</view></view><view v-if="giftProducts.length>0&&giftProducts.length<config.maxGifts" class="notice gift-shortage">后台当前仅配置{{giftProducts.length}}件{{query.type==='trial'?'体验':'贵宾'}}礼品，达到{{config.maxGifts}}件后才可领取</view><view v-if="!giftProducts.length" class="empty">暂无数据~</view><view v-else class="grid"><view v-for="p in giftProducts" :key="p.id" class="gift-card" @click="productPage(p)"><image :src="p.image||'/static/assets/product-placeholder.jpg'" mode="aspectFill"/><view class="gift-copy"><view class="gift-name">{{p.name}}</view><view class="between gift-actions"><template v-if="isGiftClaimed(p.id)"><button class="outline" @click.stop="productPage(p)">查看详情</button><button v-if="p.kind==='service'" class="pill" @click.stop="startGiftBooking(p)">预约使用</button></template><template v-else><button class="outline" :style="selectedGifts.includes(p.id)?'background:#c98bdd;color:#fff':''" @click.stop="selectGift(p.id)">{{selectedGifts.includes(p.id)?'已选':'领取'}}</button></template><text class="muted">已领取{{p.sold||0}}件</text></view></view></view></view><view v-if="receivedGifts.length" class="claimed-gifts"><view class="section-title">已领取的礼品</view><view v-for="p in receivedGifts" :key="p.claimId+'-'+p.id" class="card claimed-gift"><image :src="p.image" mode="aspectFit"/><view class="claimed-gift-copy"><view>{{p.name}}</view><text class="muted">{{p.useStatus==='completed'?'已使用':p.useStatus==='booked'?'已预约':p.kind==='service'?'待预约使用':'待到店领取'}}</text><view class="claim-buttons"><button class="outline" @click="productPage(p)">商品详情</button><button v-if="p.kind==='service'&&p.useStatus==='available'" class="pill" @click="startGiftBooking(p)">预约使用</button><button v-else-if="p.useStatus==='booked'" class="outline" @click="open('appointments')">查看预约</button></view></view></view></view><view v-if="giftProducts.length&&!receivedGifts.length" class="bottom-actions"><button class="primary" :disabled="giftProducts.length<config.maxGifts||selectedGifts.length!==config.maxGifts" @click="claim">{{selectedGifts.length===config.maxGifts?'确认领取':'选择商品'}}</button></view></template>
  <template v-else-if="page==='login'"><view class="login-body"><image :src="config.brandLogo||'/static/brand/logo-jimeili.png'" class="login-logo" mode="aspectFit"/><view class="title">{{config.name||'暨美丽'}}</view><view class="account-login"><button class="primary wechat-login" :disabled="busy||loading" @click="wechatLogin">{{busy?'登录中…':'微信一键登录'}}</button><text v-if="!nativeDevice" class="muted">请在微信小程序内登录</text></view><text class="muted" @click="switchTab('home')">暂不登录，返回首页</text></view><view class="agreement"><text :class="['check',{on:agreed}]" @click="agreed=!agreed"/>我已阅读并同意<text class="link" @click="open('legal','?type=agreement')">《用户服务协议》</text>和<text class="link" @click="open('legal','?type=privacy')">《隐私政策》</text>，<view>首次微信登录将自动创建会员</view></view></template>
  <template v-else-if="page==='profile'"><view class="form"><view class="field" style="height:194rpx"><label>头像<text class="required">*</text></label><view class="avatar-editor" @click="chooseAvatar"><image :src="form.avatar||me.avatar||'/static/assets/avatar.png'" mode="aspectFit"/><text class="avatar-remove" @click.stop="removeAvatar">×</text></view></view><view class="field"><label>姓名<text class="required">*</text></label><input v-model="form.name" :disabled="loading" placeholder="请输入姓名" maxlength="40"/></view><view class="field" style="border:0"><label>性别<text class="required">*</text></label><text @click="!loading&&(form.gender='male')"><text :class="['check',{on:form.gender==='male'}]"/>先生</text><text style="margin-left:80rpx" @click="!loading&&(form.gender='female')"><text :class="['check',{on:form.gender==='female'}]"/>女士</text></view><button class="primary" :disabled="busy||loading" @click="saveProfile">保存信息</button></view></template>
<template v-else-if="page==='mine'"><view class="profile-head" @click="open(me.id?'profile':'login')"><image :src="me.avatar||'/static/assets/avatar.png'" class="profile-avatar"/><view><view class="title">{{me.name||config.name||'暨美丽'}}</view><view class="muted" style="margin-top:14rpx">{{me.phone?'手机号 '+me.phone:'手机号 暂未绑定'}}</view></view><image class="profile-share-icon" src="/static/reference/profile-code.png" @click.stop="open('share')"/></view><view class="stats mine-stats"><view class="stat"><view class="muted">我的积分</view><view>{{me.points||0}}个</view></view><view class="stat"><view class="muted">累计收益</view><view>0元</view></view></view><view class="vip-pool"><view>VIP积分池</view><view class="big-number">{{me.points||0}}</view></view><view v-for="(group,groupIndex) in menuGroups" :key="groupIndex" class="card menu"><template v-for="menuItem in group" :key="menuItem[1]"><button v-if="menuItem[1]==='contact'" class="menu-item menu-contact" open-type="contact" session-from="mine"><image class="menu-icon-image" :src="menuIcon(menuItem[1])" mode="aspectFit"/><text>{{menuItem[0]}}</text><text class="chevron">›</text></button><view v-else class="menu-item" @click="menuClick(menuItem)"><image class="menu-icon-image" :src="menuIcon(menuItem[1])" mode="aspectFit"/><text>{{menuItem[0]}}</text><text class="chevron">›</text></view></template></view></template>
<template v-else-if="page==='discover'"><view class="discover-head discover-points-head" :style="nativeDevice?{paddingTop:(statusBar+24)+'px'}:{}"><view class="title">积分商城</view><image class="points-banner" :src="config.pointsBanner||'/static/assets/points-banner.jpg'" mode="widthFix"/></view><view class="discover-links"><view @click="open('sign')"><image class="discover-icon" src="/static/reference/sign-on.png" mode="aspectFit"/><text>每日签到</text></view><view @click="open('points')"><image class="discover-icon" src="/static/reference/points.png" mode="aspectFit"/><text>积分收入</text></view><view @click="open('redemptions')"><image class="discover-icon" src="/static/reference/redeem.png" mode="aspectFit"/><text>兑换记录</text></view></view><view v-for="r in rows" :key="r.id" class="card reward-card"><image v-if="r.image" :src="r.image" mode="aspectFit"/><view class="between"><view><view class="title">{{r.name}}</view><view class="muted">{{r.points}}积分</view></view><button class="pill" @click="redeemReward(r)">兑换</button></view></view><view v-if="!rows.length" class="empty">暂无数据~</view></template>
  <template v-else-if="page==='addresses'"><view v-for="a in rows" :key="a.id" class="card" @click="open('address-edit','?id='+a.id)"><view class="between"><text>{{a.name}}　{{a.phone}}</text><text class="link">编辑</text></view><view class="description">{{a.city}} {{a.detail}}</view><view class="between" style="margin-top:20rpx"><text class="tag" v-if="a.isDefault">默认地址</text><text class="muted" @click.stop="deleteAddress(a)">删除</text></view></view><view v-if="!rows.length" class="empty">暂无收货地址，请先添加</view><view class="bottom-actions"><button class="primary" @click="open('address-edit')">添加地址</button></view></template>
  <template v-else-if="page==='address-edit'"><view class="form"><view v-for="f in addressFields" :key="f.key" class="field"><label>{{f.label}}<text class="required">*</text></label><template v-if="f.key==='city'">
<!-- #ifdef MP-WEIXIN -->
<picker mode="region" :disabled="loading" :value="regionValue" @change="form.city=$event.detail.value.join(' ')"><text :style="{color:form.city?'#17212c':'#c7c7c7'}">{{form.city||'选择收件城市'}}</text></picker>
<!-- #endif -->
<!-- #ifdef H5 -->
<input v-model="form.city" :disabled="loading" placeholder="输入省 / 市 / 区"/>
<!-- #endif -->
</template><input v-else v-model="form[f.key]" :disabled="loading" :type="f.key==='phone'?'number':'text'" :maxlength="f.key==='phone'?11:200" :placeholder="f.placeholder"/></view><view class="field" style="border:0"><label>设为默认</label><text @click="!loading&&(form.isDefault=!form.isDefault)"><text :class="['check',{on:form.isDefault}]"/>选中默认</text></view><button class="primary" :disabled="busy||loading" @click="saveAddress">保存地址</button></view></template>
  <template v-else-if="page==='checkout'&&product"><view class="card order-product"><image :src="product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view><view>{{product.name}}</view><view style="color:#ff3a13;margin-top:15rpx">￥{{money(unitPrice)}} / 件</view><view class="muted">购买规格：{{selectedSku?.name||(spec==='course'?'1疗程':product.kind==='goods'?'1件':'1次')}} × {{quantity}}件</view></view></view><view class="card between"><text>服务门店<text class="required">*</text></text><picker :range="stores" range-key="name" :value="storeIndex" @change="storeIndex=Number($event.detail.value)">{{chosenStore.name||'选择门店'}} ›</picker></view><view v-if="product.kind==='goods'" class="card"><view class="between"><text>收货地址<text class="required">*</text></text><text class="link" @click="open('addresses')">管理地址</text></view><picker v-if="addresses.length" :range="addresses" range-key="detail" :value="addressIndex" @change="addressIndex=Number($event.detail.value)"><view class="description">{{chosenAddress.name}} {{chosenAddress.city}} {{chosenAddress.detail}} ›</view></picker><view v-else class="description" @click="open('address-edit')">{{loading?'正在读取收货地址…':'请先添加收货地址 ›'}}</view></view><view class="card"><view class="order-line"><text>商品金额</text><text>{{money(total)}}元</text></view><view class="order-line"><text>订单金额</text><text style="color:#b96ee0">{{total}}元</text></view></view><view class="card"><input v-model="form.message" placeholder="请在这里输入您的留言" maxlength="200"/></view><view class="bottom-actions"><text style="flex:1">应付金额：<text style="color:#ff3a13">￥{{total}}</text></text><button class="primary" style="max-width:300rpx;height:74rpx" :disabled="busy||loading" @click="createOrder">立即付款</button></view></template>
  <template v-else-if="page==='orders'"><view class="tabs"><text v-for="(t,i) in orderTabs" :key="t" :class="{selected:tab===i}" @click="tab=i">{{t}}</text></view><view v-for="o in filteredRows" :key="o.id" class="card"><view class="between" style="font-size:25rpx;margin:10rpx 10rpx 12rpx"><text>{{date(o.createdAt)}}</text><text :style="{color:o.status==='pending'?'red':'#ad68d3'}">{{statusText(o.status)}}</text></view><view class="order-product" @click="open('order-detail','?id='+o.id)"><image :src="o.product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view><view>{{o.product.name}}</view><view class="muted">购买 {{o.product.selectedSku?.name||(o.spec==='course'?'1疗程':o.spec==='single'?'1次':'')}} {{o.quantity}}件</view><text class="price" style="font-weight:400;font-size:28rpx">￥{{money(o.total)}}</text></view></view><view class="order-buttons"><text style="font-size:23rpx;margin-right:auto">订单应付<text class="price" style="font-size:25rpx">{{o.total}}</text>元</text><button v-if="o.status==='pending'" @click="cancelOrder(o)">取消订单</button><button @click="open('order-detail','?id='+o.id)">订单详情</button><button v-if="o.status==='pending'" class="pay" @click="pay(o)">马上支付</button></view></view><view class="empty">{{filteredRows.length?'已经到底了～':'暂无数据～'}}</view></template>
  <template v-else-if="page==='order-detail'&&order"><view class="card"><view class="title">{{statusText(order.status)}}</view><view class="description">{{order.status==='pending'?'下单2小时内未支付自动取消~':order.paymentMode==='offline'?'门店已确认线下收款':order.paymentStatus==='paid'?'微信支付已完成':order.status==='aftersale'?(order.refundNote||'售后退款处理中'):'感谢您的惠顾'}}</view></view><view class="card"><view class="title" style="font-weight:400">服务门店信息</view><view class="notice order-store-note">以下是到店服务门店信息，不是收货地址</view><view class="order-line"><text>门店名称</text><text>{{orderStore.name}}</text></view><view class="order-line"><text>门店位置</text><text>{{orderStore.address}}</text></view><view class="order-line"><text>联系人</text><text>{{orderStore.phone}} {{orderStore.contact}}</text></view></view><view class="card order-product"><image :src="order.product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view><view>{{order.product.name}}</view><view class="muted">规格：{{order.product.selectedSku?.name||(order.spec==='course'?'1疗程':order.spec==='single'?'1次':'')}}<view>￥{{money(order.price)}}× {{order.quantity}}件</view></view><text class="price" style="font-size:28rpx;font-weight:400">￥{{money(order.total)}}</text></view></view><view class="card"><view class="order-line"><text>商品金额</text><text>{{money(order.total)}}元</text></view><view class="order-line"><text>应付金额</text><text>{{money(order.total)}}元</text></view></view><view v-if="order.address" class="card"><view>收货信息</view><view class="description">{{order.address.name}} {{order.address.phone}}<view>{{order.address.city}} {{order.address.detail}}</view></view></view><view class="card"><view>订单信息</view><view class="order-line"><text>订单编号</text><text @click="copy(order.number)">{{order.number}} [复制]</text></view><view class="order-line"><text>下单时间</text><text>{{date(order.createdAt)}}</text></view><view v-if="order.tracking" class="card"><view>物流 / 取货信息</view><view class="description">{{order.tracking}}</view></view></view><view class="bottom-actions"><button class="outline" @click="open('orders')">返回列表</button><button v-if="order.status==='pending'" class="outline" @click="cancelOrder(order)">取消订单</button><button v-if="order.status==='pending'" class="pill" @click="pay(order)">马上支付</button><button v-if="order.status==='ready'" class="pill" @click="open('appointments')">预约服务</button></view></template>
  <template v-else-if="page==='appointments'"><view class="tabs"><text v-for="(t,i) in ['待预约','已预约','已完成']" :key="t" :class="{selected:tab===i}" @click="tab=i">{{t}}</text></view><view v-for="a in filteredRows" :key="a.id" class="card"><view class="title">{{a.name||(a.product&&a.product.name)}}</view><view class="description">{{a.date||'待选择预约时间'}} {{a.time||''}}</view><button v-if="tab===0" class="pill" style="margin-top:20rpx" @click="open('booking','?orderId='+a.id)">立即预约</button></view><view v-if="tab===0" v-for="p in availableClaimGifts" :key="p.claimId+'-'+p.id" class="card"><view class="title">{{p.name}}</view><view class="description">已领取礼品，可预约到店使用</view><button class="pill" @click="startGiftBooking(p)">预约使用</button></view><view v-if="!filteredRows.length&&!(tab===0&&availableClaimGifts.length)" class="empty">暂无数据～</view><view class="bottom-actions" style="justify-content:center"><button class="pill" style="padding:20rpx 38rpx" @click="startBooking">我要预约(还可预约{{availableOrders.length+availableClaimGifts.length}}次)</button></view></template>
  <template v-else-if="page==='booking'"><view class="form"><view v-if="query.claimId" class="field"><label>服务门店</label><picker :range="stores" range-key="name" :value="storeIndex" @change="storeIndex=Number($event.detail.value)">{{chosenStore.name||'选择门店'}}</picker></view><view class="field"><label>预约日期</label><picker mode="date" :start="today" :value="form.date" @change="form.date=$event.detail.value">{{form.date||'选择预约日期'}}</picker></view><view class="field"><label>预约时间</label><picker :range="times" @change="form.time=times[$event.detail.value]">{{form.time||'选择预约时间'}}</picker></view><button class="primary" :disabled="busy||loading" @click="book">确认预约</button></view></template>
  <template v-else-if="page==='share'"><view class="share-page"><view class="share-hero-frame"><image src="/static/assets/share-art.jpg" class="share-hero-art" mode="widthFix"/></view><view class="share-card-frame"><image src="/static/reference/share-card.png" mode="scaleToFill"/><view class="share-qr"><image v-if="shareImage||config.customerQr" :src="shareImage||config.customerQr" class="share-qr-image" mode="aspectFit" show-menu-by-longpress @longpress="handleShareLongpress"/><view v-else class="share-empty">{{me.id?'分享码加载中…':'请先登录'}}<view>{{inviteCode}}</view></view></view></view><view class="share-code-actions"><button @click="copy(inviteCode)">复制邀请码</button><button @click="previewShare">查看分享码</button></view></view></template>
  <template v-else-if="page==='about'"><image :src="config.brandLogo||'/static/brand/logo-jimeili.png'" class="about-logo"/><view class="about-title">{{config.name||'暨美丽'}}</view><view class="card" style="margin:0 78rpx;padding:38rpx"><view class="field"><label style="width:auto;flex:1">小程序版本</label>{{config.version}}</view><view class="field" @click="open('legal','?type=agreement')"><label style="width:auto;flex:1">用户服务协议</label>点击查看</view><view class="field" style="border:0" @click="open('legal','?type=privacy')"><label style="width:auto;flex:1">用户隐私政策</label>点击查看</view></view></template>
  <template v-else-if="page==='legal'"><view class="legal-page"><view class="legal-title">{{query.type==='privacy'?'隐私政策':'用户服务协议'}}</view><view class="legal-date">生效日期：2026年09月29日</view><view class="card rules">{{config[query.type]}}</view></view></template>
  <template v-else-if="page==='points'"><view class="purple-top"><view class="big-number">{{me.points||0}}</view><view>我的积分</view></view><view class="stats points-stats"><view class="stat selected"><view class="muted">积分收入</view><view>{{me.points||0}}个</view></view><view class="stat"><view class="muted">积分支出</view><view>{{pointsSpent}}分</view></view></view><view v-for="r in rows" :key="r.id" class="card ledger-card"><view>{{r.name}}</view><view class="between muted"><text>{{date(r.createdAt)}}</text><text class="link">{{r.amount>0?'+':''}}{{r.amount}}积分</text></view></view><view v-if="!rows.length" class="empty">暂无数据~</view></template><template v-else-if="page==='sign'"><view class="purple-top sign-top"><view class="big-number">{{me.points||0}}</view><view>我的积分</view></view><view class="card points-card"><view class="between"><view>已连续签到<br/><text class="link">{{me.streak||0}}天</text></view><button class="pill" :disabled="me.lastSign===today" @click="signIn">{{me.lastSign===today?'今日已签到':'立即签到+'+(config.signPoints||100)}}</button></view><view class="days"><view v-for="dayLabel in signDays" :key="dayLabel"><text>+{{config.signPoints||100}}</text><view class="day-star"><image :src="me.lastSign===today?'/static/reference/sign-on.png':'/static/reference/sign-off.png'" mode="aspectFit"/></view></view></view><view class="timeline"><text v-for="i in 7" :key="i"/></view></view></template><template v-else-if="page==='redemptions'"><view v-for="r in rows" :key="r.id" class="card redemption-card"><view class="between"><text class="title">{{r.name}}</text><text class="tag">已兑换</text></view><view class="redemption-meta"><text>{{date(r.createdAt)}}</text><text>{{r.points}}积分</text></view></view><view v-if="!rows.length" class="empty">暂无兑换记录~</view></template><template v-else-if="page==='activities'"><view class="card vip-channel-card"><view class="vip-poster"><image src="/static/assets/vip-benefits-generated.png" mode="widthFix"/><view class="vip-poster-brand">暨美丽</view><view class="vip-poster-title">线上商城会员专属权益</view><view class="vip-poster-list"><view v-for="(item,index) in vipBenefits" :key="item"><text>{{index+1}}、</text>{{item}}</view></view></view><view class="title">暨美丽超级VIP</view><view class="description">加入会员，享受专属礼遇与到店服务。</view></view><view v-for="r in rows" :key="r.id" class="card activity-card"><image v-if="r.image" :src="r.image||'/static/assets/product-placeholder.jpg'" mode="widthFix" class="wide-img"/><view class="title">{{r.name}}</view><view class="description">{{r.description||'活动详情请咨询门店'}}</view><view v-if="r.startAt||r.endAt" class="muted">活动时间：{{r.startAt||'即日起'}} 至 {{r.endAt||'另行通知'}}</view><button v-if="r.productId&&activityProduct(r)" class="primary activity-button" @click="productPage(activityProduct(r))">查看商品并购买</button></view><view v-if="!rows.length" class="empty">暂无活动</view></template><template v-else><view v-for="r in rows" :key="r.id" class="card"><image v-if="r.image" :src="r.image||'/static/assets/product-placeholder.jpg'" mode="widthFix" class="wide-img"/><view class="title">{{r.name}}</view><view class="description">{{r.description||date(r.createdAt)}}</view><text v-if="r.phone" class="link" @click="call(r.phone)">{{r.phone}}</text></view><view v-if="!rows.length" class="empty">暂无数据～</view></template>
  <view v-if="isTab" class="tabbar"><view v-for="t in mainTabs" :key="t.page" :class="['tabitem',{active:page===t.page}]" @click="switchTab(t.page)"><image :src="tabIcon(t.page)" mode="aspectFit"/>{{t.name}}</view></view>
  <view v-if="sheet&&product" class="overlay" @click="sheet=false"><view class="sheet" @click.stop><text class="close" @click="sheet=false">×</text><view class="sheet-head row"><image :src="product.image||'/static/assets/product-placeholder.jpg'" mode="aspectFit" @error="imageError"/><view><view style="font-size:34rpx">{{product.name}}</view><view style="color:#df25ff;margin:18rpx 0">￥{{unitPrice}}</view><text class="muted">已选：{{selectedSku?.name||(spec==='course'?'1疗程':product.kind==='goods'?'1件':'1次')}}，{{quantity}}件</text></view></view><view>选择商品规格</view><view v-if="product.skus&&product.skus.length" class="specs sku-specs"><text v-for="sku in product.skus" :key="sku.id" :class="['spec',{selected:sku.id===skuId,disabled:sku.enabled===false||sku.stock<1}]" @click="sku.enabled!==false&&sku.stock>0&&(skuId=sku.id)">{{sku.name}} ¥{{money(sku.price)}}</text></view><view v-else class="specs"><text :class="['spec',{selected:spec==='single'}]" @click="spec='single'">{{product.kind==='goods'?'1件':'1次'}}</text><text v-if="product.coursePrice!==undefined&&product.coursePrice!==null" :class="['spec',{selected:spec==='course'}]" @click="spec='course'">1疗程</text></view><view class="between"><text>选择购买数量</text><view class="quantity"><button :disabled="quantity<=1" @click="quantity--">−</button>{{quantity}}<button :disabled="quantity>=(selectedSku?selectedSku.stock:product.stock)||quantity>=99" @click="quantity++">+</button></view></view><button class="primary" @click="checkout">立即购买</button></view></view>
 </view>
</template>
<script>
import { api, go, toast, money } from '../common/api.js'
import { uploadAvatar } from '../common/avatar.js'
import { fallbackCatalogue } from '../common/fallback-catalogue.js'
const titles={product:'商品详情',stores:'所有门店',gifts:'',login:'',profile:'个人信息',appointments:'我的预约',booking:'在线预约',activities:'活动专区',alliances:'百业联盟',checkout:'确认下单','order-detail':'订单详情',orders:'我的订单',addresses:'我的收件地址','address-edit':'添加地址',shares:'我分享的人',earnings:'收益明细',about:'关于我们',share:'我的分享码',legal:'服务条款',points:'我的积分',sign:'签到有礼',redemptions:'兑换记录'}
export default {
 props:{page:String,query:{type:Object,default:()=>({})}},
 data(){return{nativeDevice:false,statusBar:0,config:{},products:[],categories:[],stores:[],homeModules:[],me:{},rows:[],claimRows:[],orders:[],addresses:[],order:null,loading:false,error:'',formReady:false,authPrompted:false,shareImage:'',demoMode:false,paymentMode:'off',busy:false,retryTimer:null,tab:0,mallCategory:'all',sheet:false,spec:'single',skuId:'',quantity:1,storeIndex:0,addressIndex:0,agreed:false,form:{},selectedGifts:[],vipBenefits:["超级VIP动态收益：首次-50%，持续-10%","超级VIP静态收益：营业额5%","每月赠送5张VIP亲友卡","可持续分红两年，到期可选择退VIP或续VIP","享受本店超级VIP服务，拥有所有新项目免费体验权","本店将为超级VIP定制私人礼品"],times:['09:00','10:00','11:00','14:00','15:00','16:00','17:00','18:00'],mainTabs:[{page:'home',name:'首页'},{page:'mall',name:'商城'},{page:'discover',name:'发现'},{page:'mine',name:'我的'}],shortcuts:[{label:'体验卡',page:'gifts',query:'?type=trial',asset:'trial',color:'#fff'},{label:'贵宾卡',page:'gifts',query:'?type=vip',asset:'vip',color:'#f4ca72'},{label:'邀请码',page:'share',asset:'share',color:'#fff'}],menus:[['我的订单','orders'],['收件地址','addresses'],['我的分享','shares'],['我的收益','earnings'],['联系客服','contact'],['关于我们','about'],['退出登录','logout']],orderTabs:['全部','待付款','待使用','待取货','已完成','售后'],addressFields:[{key:'name',label:'收件人姓名',placeholder:'输入收件人姓名'},{key:'phone',label:'联系电话',placeholder:'输入联系电话'},{key:'city',label:'收件城市',placeholder:'输入省 / 市 / 区'},{key:'detail',label:'详细地址',placeholder:'输入详细地址'}]}},
 computed:{
  isTab(){return ['home','mall','discover','mine'].includes(this.page)},
  bottomSpace(){return !this.isTab},
  title(){if(this.page==='gifts')return this.query?.type==='trial'?'领取VIP体验商品':'领取尊享贵宾商品';return titles[this.page]||''},
  nativeNavStyle(){return this.nativeDevice?{paddingTop:this.statusBar+'px',height:(112+this.statusBar)+'px'}:{}},
  nativeBackStyle(){return this.nativeDevice?{top:(this.statusBar+56)+'px'}:{}},
  featuredCategoryId(){return (Array.isArray(this.categories)?this.categories:[]).find(x=>x&&x.enabled!==false&&String(x.name||'').includes('特色'))?.id||'category-featured'},
  goodsCategoryId(){return (Array.isArray(this.categories)?this.categories:[]).find(x=>x&&x.enabled!==false&&String(x.name||'').includes('优选'))?.id||'category-goods'},
  featuredProducts(){return (Array.isArray(this.products)?this.products:[]).filter(p=>p&&p.trialOnly!==true&&p.enabled!==false&&p.status!=='offline'&&p.home!==false&&this.productCategoryKey(p)==='featured').sort((a,b)=>(a.sort||0)-(b.sort||0)).slice(0,2)},
  serviceProducts(){return this.featuredProducts},
  goodsProducts(){return (Array.isArray(this.products)?this.products:[]).filter(p=>p&&p.trialOnly!==true&&p.enabled!==false&&p.status!=='offline'&&p.home!==false&&this.productCategoryKey(p)==='goods').sort((a,b)=>(a.sort||0)-(b.sort||0)).slice(0,2)},
  mallCategories(){const cats=(Array.isArray(this.categories)?this.categories:[]).filter(c=>c&&c.enabled!==false).slice().sort((a,b)=>(a.sort||0)-(b.sort||0));return [{id:'all',name:'全部'},...cats]},
  selectedMallCategoryName(){return this.mallCategories.find(c=>c.id===this.mallCategory)?.name||'全部'},
  mallProducts(){const list=(Array.isArray(this.products)?this.products:[]).filter(p=>p&&p.trialOnly!==true&&p.enabled!==false&&p.status!=='offline');if(this.mallCategory==='all')return list;return list.filter(p=>p.categoryId===this.mallCategory||String(p.groupIds||'').split(/[,，]/).map(v=>v.trim()).includes(this.mallCategory))},
  product(){const id=this.query&&this.query.id;return id?(this.products||[]).find(p=>p&&p.id===id)||null:null},
  selectedSku(){return this.product?.skus?.find(s=>s&&s.id===this.skuId&&s.enabled!==false&&s.stock>0)||this.product?.skus?.find(s=>s&&s.id===this.skuId)||null},
  unitPrice(){if(!this.product)return 0;return Number(this.selectedSku?.price??(this.spec==='course'?this.product.coursePrice:(this.product.memberPrice??this.product.price)))||0},
  total(){return Math.round(this.unitPrice*Math.max(1,Number(this.quantity)||1)*100)/100},
  chosenStore(){return this.stores?.[this.storeIndex]||this.stores?.find(s=>s.enabled!==false)||{}},
  chosenAddress(){return this.addresses?.[this.addressIndex]||{}},
  orderStore(){return this.stores?.find(s=>s.id===this.order?.storeId)||this.stores?.find(s=>s.enabled!==false)||{}},
  filteredRows(){const rows=Array.isArray(this.rows)?this.rows:[];if(this.page==='orders'){const status=['','pending','ready','shipping','completed','aftersale'][this.tab]||'';return status?rows.filter(r=>r.status===status):rows}if(this.page==='appointments'){const status=['','booked','completed'][this.tab]||'';return status?rows.filter(r=>r.status===status):rows}return rows},
  giftClaims(){return Array.isArray(this.claimRows)?this.claimRows:[]},
  giftProducts(){const trial=this.query?.type==='trial';return (Array.isArray(this.products)?this.products:[]).filter(p=>p&&p.enabled!==false&&p.status!=='offline'&&p.stock>0&&(trial?p.trial===true:p.gift===true))},
  receivedGifts(){return this.giftClaims.flatMap(c=>(Array.isArray(c.products)?c.products:[]).map(p=>({...p,claimId:c.id})))},
  availableClaimGifts(){return this.receivedGifts.filter(p=>p.useStatus==='available')},
  giftEligible(){return this.query?.type==='trial'||this.me?.invited===true},
  availableOrders(){return (Array.isArray(this.orders)?this.orders:[]).filter(o=>o&&o.status==='ready'&&o.product?.kind==='service')},
  menuGroups(){const menus=Array.isArray(this.menus)?this.menus:[];return menus.length?[menus.slice(0,4),menus.slice(4)]:[]},
  inviteCode(){return this.me?.id?String(this.me.id).slice(0,8).toUpperCase():''},
  pointsSpent(){return (Array.isArray(this.rows)?this.rows:[]).filter(r=>Number(r.amount)<0).reduce((n,r)=>n+Math.abs(Number(r.amount)||0),0)},
  signDays(){return ['一','二','三','四','五','六','日']},
  today(){const d=new Date();const p=v=>String(v).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())},
  regionValue(){return String(this.form?.city||'').split(/[ ,，]+/).filter(Boolean).slice(0,3)}
 }, mounted(){
// #ifdef MP-WEIXIN
this.nativeDevice=true;this.statusBar=uni.getSystemInfoSync().statusBarHeight||0;
// #endif
if(this.query.invite)uni.setStorageSync('invite',this.query.invite);this.spec=this.query.spec||'single';this.mallCategory=this.query.category||'all';this.quantity=Math.max(1,Number(this.query.quantity)||1);this.refresh()},
 methods:{money,toast,productCategoryKey(p){if(!p)return '';const id=String(p.categoryId||'');if(id===this.goodsCategoryId||id==='category-goods'||String(p.kind)==='goods')return 'goods';if(id===this.featuredCategoryId||id==='category-featured')return 'featured';const c=(Array.isArray(this.categories)?this.categories:[]).find(x=>x&&x.id===p.categoryId);return c&&String(c.name||'').includes('优选')?'goods':'featured'},isGiftClaimed(id){return this.giftClaims.some(c=>(c.productIds||[]).includes(id))},giftClaimFor(id){return this.giftClaims.find(c=>(c.productIds||[]).includes(id))},redeemReward(r){if(!this.me.id)return go('login');return this.run(async()=>{await api('/redemptions','POST',{rewardId:r.id});toast('兑换成功');await this.refresh()})},signIn(){if(!this.me.id)return go('login');return this.run(async()=>{this.me=await api('/sign','POST');toast('签到成功');await this.refresh()})},logout(){return this.run(async()=>{await api('/auth/logout','POST');uni.removeStorageSync('token');this.me={};this.rows=[];this.orders=[];this.addresses=[];toast('已退出登录');this.switchTab('mine')})},wechatLogin(){if(!this.agreed)return toast('请先阅读并同意协议');
// #ifndef MP-WEIXIN
return toast('请在微信小程序内使用微信一键登录');
// #endif
// #ifdef MP-WEIXIN
return this.run(async()=>{let result;try{result=await uni.login({provider:'weixin'})}catch{throw new Error('未能获取微信登录凭证，请重试')}if(!result.code)throw new Error('未能获取微信登录凭证，请重试');const r=await api('/auth/wechat','POST',{code:result.code,invite:uni.getStorageSync('invite')||''});uni.setStorageSync('token',r.token);this.me=r.user;toast('登录成功');this.back()});
// #endif
},open:go,previewShare(){if(this.shareImage)uni.previewImage({urls:[this.shareImage]});else toast('分享码尚未生成')},handleShareLongpress(){if(this.shareImage)toast('请在弹出的菜单中选择“识别图中二维码”')},saveShareImage(){if(!this.shareImage)return toast('分享码尚未生成');
// #ifdef H5
return this.previewShare();
// #endif
// #ifdef MP-WEIXIN
this.run(async()=>{const file=await new Promise((resolve,reject)=>uni.downloadFile({url:this.shareImage,success:resolve,fail:reject}));if(file.statusCode!==200)throw new Error('分享码下载失败');await new Promise((resolve,reject)=>uni.saveImageToPhotosAlbum({filePath:file.tempFilePath,success:resolve,fail:reject}));toast('分享码已保存到相册')});
// #endif
},imageError(e){console.warn('商品图片加载失败',e.detail)},tabIcon(p){if(p==='mall'&&this.page==='mall')return '/static/icons/mall-active.svg';return '/static/reference/tab-'+p+(this.page===p?'-active':'')+'.png'},menuIcon(p){return '/static/reference/menu-'+(['orders','addresses','shares','earnings','contact'].includes(p)?p:p==='appointments'?'orders':'contact')+'.png'},async chooseAvatar(){await this.run(async()=>{const result=await uni.chooseImage({count:1,sizeType:['compressed']});const avatar=await uploadAvatar(result.tempFilePaths[0]);this.form.avatar=avatar.avatar;this.me.avatar=avatar.avatar;toast('头像已更新')})},removeAvatar(){this.run(async()=>{const r=await api('/me/avatar','DELETE');this.form.avatar=r.avatar;this.me.avatar=r.avatar})},homeProducts(kind){return this.products.filter(p=>p.home&&p.kind===kind)},menuClick(m){if(m[1]==='logout')return this.logout();if(m[1]==='contact')this.contact();else go(m[1])},back(){const pages=getCurrentPages();if(pages.length>1)uni.navigateBack();else this.switchTab('home')},switchTab(p){uni.switchTab({url:'/pages/'+p+'/index'})},productPage(p){this.skuId=p?.skus?.find(s=>s.enabled!==false)?.id||'';go('product','?id='+p.id+(this.skuId?'&skuId='+this.skuId:''))},homeModuleClick(module){if(module.targetType==='product'&&module.targetId){const p=this.products.find(x=>x.id===module.targetId);if(p)return this.productPage(p)}if(module.targetType==='category'&&module.targetId)return go('mall','?category='+module.targetId);if(module.targetType==='activity')return go('activities');if(module.targetType==='store')return go('stores');if(module.type==='notice')return toast(module.description||module.title)},activityProduct(r){return this.products.find(p=>p.id===r.productId)},date(d){if(!d)return '';const t=new Date(new Date(d).getTime()+8*3600000);const p=v=>String(v).padStart(2,'0');return t.getUTCFullYear()+'-'+p(t.getUTCMonth()+1)+'-'+p(t.getUTCDate())+' '+p(t.getUTCHours())+':'+p(t.getUTCMinutes())+':'+p(t.getUTCSeconds())},statusText(s){return {pending:'待付款',ready:'待使用',shipping:'待取货',completed:'已完成',cancelled:'已取消',aftersale:'售后'}[s]||s},async run(fn){if(this.busy)return;this.busy=true;try{await fn()}catch(e){toast(e.message)}finally{this.busy=false}},async refresh(){this.loading=true;this.error='';try{const data=await api('/bootstrap');Object.assign(this,data);uni.setStorageSync('catalogue',{config:this.config,products:this.products,categories:this.categories,stores:this.stores,homeModules:this.homeModules,demoMode:this.demoMode,paymentMode:this.paymentMode});this.times=String(this.config.appointmentTimes||'09:00,10:00,11:00,14:00,15:00,16:00,17:00,18:00').split(',').map(v=>v.trim()).filter(Boolean);this.shortcuts=[{label:this.config.shortcutTrialLabel||'体验卡',page:'gifts',query:'?type=trial',asset:'trial',color:'#fff'},{label:this.config.shortcutVipLabel||'贵宾卡',page:'gifts',query:'?type=vip',asset:'vip',color:'#f4ca72'},{label:this.config.shortcutShareLabel||'邀请码',page:'share',asset:'share',color:'#fff'}];if(this.page==='mall'&&!this.mallCategories.some(c=>c.id===this.mallCategory))this.mallCategory='all';if(['product','checkout'].includes(this.page)&&!this.skuId)this.skuId=this.query.skuId||this.product?.skus?.find(s=>s.enabled!==false&&s.stock>0)?.id||'';if(uni.getStorageSync('token')){try{await api('/auth/refresh','POST');this.me=await api('/me')}catch(e){uni.removeStorageSync('token');this.me={}}}const privatePages=['profile','orders','order-detail','addresses','address-edit','appointments','booking','checkout','shares','earnings','points','sign','redemptions'];if(privatePages.includes(this.page)&&!this.me.id){if(!this.authPrompted){this.authPrompted=true;go('login')}return}const endpoints={discover:'rewards',activities:'activities',alliances:'alliances',orders:'orders',addresses:'addresses',appointments:'appointments',shares:'shares',earnings:'earnings',points:'ledger',redemptions:'redemptions'};if(endpoints[this.page])this.rows=await api('/'+endpoints[this.page]);if(this.me.id&&['gifts','appointments'].includes(this.page))this.claimRows=await api('/claims');if(this.page==='profile'&&!this.formReady){this.form={name:this.me.name,gender:this.me.gender,avatar:this.me.avatar};this.formReady=true}if(this.page==='address-edit'&&this.query.id&&!this.formReady){this.form=(await api('/addresses')).find(a=>a.id===this.query.id)||{};this.formReady=true}if(this.page==='checkout'){this.addresses=await api('/addresses');const selected=this.addresses.findIndex(a=>a.isDefault);if(selected>=0)this.addressIndex=selected}if(this.page==='order-detail')this.order=await api('/orders/'+this.query.id);if(this.page==='share')try{this.shareImage=(await api('/share-code')).image}catch(e){this.shareImage=''}if(this.page==='appointments')this.orders=await api('/orders')}catch(e){const cached=uni.getStorageSync('catalogue');const data=cached&&cached.products&&cached.products.length?cached:fallbackCatalogue;Object.assign(this,JSON.parse(JSON.stringify(data)));this.error='网络连接暂时不稳定，当前显示已保存内容'}finally{this.loading=false}},checkAgreement(){if(!this.agreed)toast('请先阅读并同意协议')},checkout(){if(!this.product)return toast('商品不存在或已下架');if(this.product.skus?.length&&!this.selectedSku)return toast('请选择有库存的规格');if(this.quantity>(this.selectedSku?.stock??this.product.stock))return toast('所选规格库存不足');if(!this.me.id)return go('login');this.sheet=false;go('checkout','?id='+this.product.id+'&spec='+this.spec+'&quantity='+this.quantity+(this.skuId?'&skuId='+encodeURIComponent(this.skuId):''))},saveProfile(){return this.run(async()=>{await api('/me','PUT',this.form);toast('信息已保存');this.back()})},saveAddress(){return this.run(async()=>{await api('/addresses'+(this.query.id?'/'+this.query.id:''),this.query.id?'PUT':'POST',this.form);toast('地址已保存');this.back()})},async deleteAddress(a){const r=await uni.showModal({title:'删除地址',content:'确认删除此收货地址？'});if(r.confirm)this.run(async()=>{await api('/addresses/'+a.id,'DELETE');await this.refresh()})},createOrder(){if(!this.product)return toast('商品不存在或已下架');if(!this.chosenStore.id)return toast('请选择有效门店');if(this.product.kind==='goods'&&!this.chosenAddress.id)return toast('请先选择收货地址');return this.run(async()=>{this.orderRequestKey=this.orderRequestKey||('order-'+Date.now()+'-'+Math.random().toString(36).slice(2));const o=await api('/orders','POST',{productId:this.product.id,skuId:this.skuId,spec:this.spec,quantity:this.quantity,storeId:this.chosenStore.id,addressId:this.chosenAddress.id,message:this.form.message},{'Idempotency-Key':this.orderRequestKey});this.orderRequestKey='';uni.redirectTo({url:'/pages/order-detail/index?id='+o.id})})},async cancelOrder(o){const r=await uni.showModal({title:'取消订单',content:'确认取消此订单？'});if(r.confirm)this.run(async()=>{await api('/orders/'+o.id+'/cancel','POST');await this.refresh()})},async pay(){return toast('微信支付尚未接入，订单保持待付款')},selectGift(id){if(this.isGiftClaimed(id))return toast('该礼品已领取，可查看详情或预约使用');if(this.selectedGifts.includes(id))this.selectedGifts=this.selectedGifts.filter(x=>x!==id);else if(this.selectedGifts.length<this.config.maxGifts)this.selectedGifts.push(id);else toast('最多选择'+this.config.maxGifts+'件')},startGiftBooking(p){const c=this.giftClaims.find(c=>c.id===p.claimId)||this.giftClaimFor(p.id);if(!c)return toast('请先领取该礼品');const item=c.products?.find(x=>x.id===p.id);if(item?.useStatus!=='available')return toast(item?.useStatus==='booked'?'该礼品已预约，请在我的预约中查看':'该礼品已经使用');go('booking','?claimId='+c.id+'&productId='+p.id)},claim(){if(!this.me.id)return go('login');if(this.query.type!=='trial'&&!this.me.invited)return toast('贵宾卡仅限受邀新用户领取');return this.run(async()=>{await api('/claims','POST',{productIds:this.selectedGifts,type:this.query.type==='trial'?'trial':'vip'});toast('领取成功');this.selectedGifts=[];await this.refresh()})},startBooking(){if(this.availableClaimGifts.length)return this.startGiftBooking(this.availableClaimGifts[0]);if(!this.availableOrders.length)return toast('暂无可预约服务，请先购买服务项目');go('booking','?orderId='+this.availableOrders[0].id)},book(){if(!/^\d{4}-\d{2}-\d{2}$/.test(this.form.date||'')||!/^\d{2}:\d{2}$/.test(this.form.time||''))return toast('请选择有效的预约日期和时间');return this.run(async()=>{const payload={date:this.form.date,time:this.form.time};if(this.query.claimId){payload.claimId=this.query.claimId;payload.productId=this.query.productId;payload.storeId=this.chosenStore.id}else payload.orderId=this.query.orderId;await api('/appointments','POST',payload);toast('预约成功');this.back()})},copy(v){if(v)uni.setClipboardData({data:v});else toast('请先登录')},call(phone){if(phone)uni.makePhoneCall({phoneNumber:phone})},contact(){uni.showModal({title:'联系客服',content:'门店电话：'+(this.stores[0]?.phone||''),confirmText:'拨打电话',success:r=>{if(r.confirm)this.call(this.stores[0]?.phone)}})}}
}
</script>


























